package ffmpeg

import (
	"context"
	"fmt"
	"strconv"
	"strings"
)

// VideoSpec controls synthetic H.264 MP4 generation. Frames are generated by
// ffmpeg's lavfi sources so no network sample is ever used.
type VideoSpec struct {
	OutPath       string
	Width         int
	Height        int
	FrameCount    int
	// FrameDurations gives each frame's duration in seconds (VFR). When nil a
	// constant 1/FPS cadence is used.
	FrameDurations []float64
	KeyframeEvery  int
	StartPTS       float64 // non-zero presentation start, seconds
}

// GenerateVFRMP4 builds an H.264 MP4 with variable frame durations, sparse
// keyframes and an optional non-zero start PTS. It writes a concat-style
// demuxer manifest whose per-frame durations ffmpeg preserves as VFR.
func GenerateVFRMP4(ctx context.Context, spec VideoSpec, concatPath string) error {
	bin, _, err := Binaries()
	if err != nil {
		return err
	}
	if spec.KeyframeEvery <= 0 {
		spec.KeyframeEvery = 10
	}
	// Stage 1: render numbered still frames from a deterministic test source.
	// image2 starts numbering at 1, which writeConcat accounts for.
	pattern := trimExt(spec.OutPath) + "_src-%04d.png"
	srcArgs := []string{"-y", "-v", "error",
		"-f", "lavfi", "-i",
		fmt.Sprintf("testsrc2=size=%dx%d:rate=1", spec.Width, spec.Height),
		"-frames:v", strconv.Itoa(spec.FrameCount), "-start_number", "1", pattern}
	if _, err := run(ctx, bin, srcArgs...); err != nil {
		return fmt.Errorf("render source frames: %w", err)
	}

	// Stage 2: build a concat list carrying each frame's duration (VFR).
	if err := writeConcat(concatPath, pattern, spec.FrameCount, spec.FrameDurations); err != nil {
		return err
	}

	// Stage 3: encode with explicit sparse GOP. The concat demuxer already
	// carries per-frame durations, so VFR timestamps are preserved without an
	// fps filter; setpts only applies the non-zero presentation start.
	vf := "setpts=PTS"
	if spec.StartPTS > 0 {
		// Shift every PTS forward by StartPTS seconds (in filter timebase).
		vf = fmt.Sprintf("setpts=PTS+%f/TB", spec.StartPTS)
	}
	args := []string{"-y", "-v", "error",
		"-f", "concat", "-safe", "0", "-i", concatPath,
		"-vf", vf,
		"-c:v", "libx264", "-pix_fmt", "yuv420p",
		"-g", strconv.Itoa(spec.KeyframeEvery),
		"-keyint_min", strconv.Itoa(spec.KeyframeEvery),
		"-sc_threshold", "0",
		"-movflags", "+faststart",
		spec.OutPath}
	if _, err := run(ctx, bin, args...); err != nil {
		return fmt.Errorf("encode vfr mp4: %w", err)
	}
	return nil
}

// GenerateAudioMP4 builds a short AAC-in-MP4 fixture from a sine source.
func GenerateAudioMP4(ctx context.Context, outPath string, durationS int, sampleRate int) error {
	bin, _, err := Binaries()
	if err != nil {
		return err
	}
	args := []string{"-y", "-v", "error",
		"-f", "lavfi", "-i",
		fmt.Sprintf("sine=frequency=1000:sample_rate=%d:duration=%d", sampleRate, durationS),
		"-c:a", "aac", "-b:a", "64k", "-movflags", "+faststart", outPath}
	if _, err := run(ctx, bin, args...); err != nil {
		return fmt.Errorf("encode aac mp4: %w", err)
	}
	return nil
}

func trimExt(path string) string {
	if i := strings.LastIndex(path, "."); i > 0 {
		return path[:i]
	}
	return path
}
